#!/usr/bin/env bash
#
# <slug> rollout — generated by the sarthi-feature skill from
# .claude/skills/sarthi-feature/rollout-template.sh.
#
# The OWNER runs this from the laptop, after the feature's commits are pushed
# to origin/main:
#
#   bash docs/features/<slug>-rollout.sh
#
# What it does:
#   1. checks local HEAD == origin/main (what you reviewed is what ships)
#   2. on prod (ssh vultr, /root/mojud/Sarthi): git pull, checks the commit,
#      pg_dump backup to /root/backups/sarthi-<stamp>.sql.gz
#   3. applies MIGRATIONS in order, each in one transaction, as the sarthi
#      user (so new tables are owned correctly)
#   4. server/deploy/redeploy.sh — builds, restarts, health-checks, and rolls
#      the binary back by itself if /healthz fails
#   5. /healthz from outside + smoke() checks
#   6. scripts/publish-apps.sh if PUBLISH_APPS=1 (APKs must already be built)
#
# Rollback:
#   binary   — automatic in redeploy.sh; by hand: ssh vultr, then in
#              /root/mojud/Sarthi: git checkout <previous commit> &&
#              server/deploy/redeploy.sh
#   database — apply the migration's .down.sql as the sarthi user, or restore
#              the backup this run printed.
set -euo pipefail

SLUG="<slug>"
MIGRATIONS=()      # e.g. (0015_example.up.sql) — file names in server/migrations
PUBLISH_APPS=0     # 1 = publish scripts/*-release.apk to apps.mojud.life afterwards
API="https://api.mojud.life"
ADMIN_TOKEN_FILE="$HOME/Documents/MOJUD_Keys/sarthi-admin-token.txt"

REPO_ROOT="$(git -C "$(dirname "${BASH_SOURCE[0]}")" rev-parse --show-toplevel)"
STAMP="$(date +%Y%m%d-%H%M%S)"

log() { printf '\n\033[1;34m==>\033[0m \033[1m%s\033[0m\n' "$*"; }
die() { printf '\n\033[1;31merror:\033[0m %s\n' "$*" >&2; exit 1; }

# expect_status <code> <curl args…> — fails unless the response has that status.
expect_status() {
  local want=$1; shift
  local got
  got="$(curl -s -o /dev/null -w '%{http_code}' --max-time 15 "$@")"
  [ "$got" = "$want" ] || die "$* → HTTP $got (want $want)"
  echo "  ok $want  ${*: -1}"
}

# admin_get <path> — GET with the admin token (never echoed), pretty-printed.
admin_get() {
  curl -fsS --max-time 15 -H "Authorization: Bearer $(cat "$ADMIN_TOKEN_FILE")" "$API$1" | python3 -m json.tool
}

# smoke — the feature's own checks against prod, after the deploy.
smoke() {
  :
}

# --- 1. what ships is what was pushed ----------------------------------------
for m in "${MIGRATIONS[@]}"; do
  [ -f "$REPO_ROOT/server/migrations/$m" ] || die "no such migration: server/migrations/$m"
done
timeout 60 git -C "$REPO_ROOT" fetch -q origin || die "git fetch origin failed or timed out"
[ -z "$(git -C "$REPO_ROOT" status --porcelain --untracked-files=no)" ] \
  || die "uncommitted changes in tracked files — commit or stash first"
[ "$(git -C "$REPO_ROOT" rev-parse HEAD)" = "$(git -C "$REPO_ROOT" rev-parse origin/main)" ] \
  || die "local HEAD is not origin/main — push (or pull) first"
WANT="$(git -C "$REPO_ROOT" rev-parse --short=12 origin/main)"
log "Shipping $SLUG at $WANT"

# --- 2–4. on the server -------------------------------------------------------
ssh vultr bash -s -- "$STAMP" "$WANT" "${MIGRATIONS[@]}" <<'REMOTE'
set -euo pipefail
STAMP=$1; WANT=$2; shift 2
cd /root/mojud/Sarthi

echo "==> git pull"
git pull --ff-only
GOT="$(git rev-parse --short=12 HEAD)"
[ "$GOT" = "$WANT" ] || { echo "prod is at $GOT, expected $WANT" >&2; exit 1; }

echo "==> backup"
mkdir -p /root/backups
BACKUP="/root/backups/sarthi-$STAMP.sql.gz"
(cd /tmp && sudo -u postgres pg_dump sarthi) | gzip > "$BACKUP"
echo "    $BACKUP ($(du -h "$BACKUP" | cut -f1))"

if [ $# -gt 0 ]; then
  set -a; . server/.env.prod; set +a
  for m in "$@"; do
    echo "==> migration $m"
    PGPASSWORD="$POSTGRES_PASSWORD" psql -h localhost -U sarthi -d sarthi \
      -v ON_ERROR_STOP=1 -1 -f "server/migrations/$m"
  done
fi

echo "==> redeploy"
server/deploy/redeploy.sh
REMOTE

# --- 5. from outside ----------------------------------------------------------
log "Health from outside"
curl -fsS --max-time 15 "$API/healthz"; echo
log "Smoke checks"
smoke

# --- 6. apps ------------------------------------------------------------------
if [ "$PUBLISH_APPS" = 1 ]; then
  log "Publishing APKs"
  "$REPO_ROOT/scripts/publish-apps.sh"
fi

log "Done: $SLUG at $WANT (backup /root/backups/sarthi-$STAMP.sql.gz)"
